const assert = require('node:assert/strict')
const fs = require('node:fs')
const path = require('node:path')
const pedido = fs.readFileSync(path.join(__dirname, '..', 'app/orcamento-rapido/page.tsx'), 'utf8')
const identificacao = fs.readFileSync(path.join(__dirname, '..', 'app/clientes/identificar/page.tsx'), 'utf8')
const automatico = pedido.match(/\/\/ O primeiro nome preenchido[\s\S]*?\}, \[rascunhoCarregado, rascunhoIniciado,[^\n]+/)?.[0]
assert.ok(automatico, 'Salvamento automático de rascunho presente')
assert.match(automatico, /!clienteNome\.trim\(\)/, 'Só grava após identificar cliente')
assert.doesNotMatch(automatico.split('const timer')[0], /!rascunhoUsuarioId|!rascunhoIniciado/, 'Falta temporária de sessão não deve impedir rascunho')
assert.match(automatico, /salvarRascunho\(rascunhoChave, montarRascunhoAtual\(\)\)/, 'Continua usando armazenamento local existente')
assert.match(pedido, /disabled=\{salvandoRascunhoManual \|\| !clienteNome\.trim\(\)\}/, 'Salvamento manual disponível sem esperar perfil')
assert.match(identificacao, /Promise\.allSettled\(/, 'Leitura de rascunhos não silencia falha do armazenamento')
assert.match(identificacao, /Não foi possível consultar os rascunhos deste navegador/, 'Falha local visível')
assert.match(identificacao, /Rascunhos são guardados no navegador e aparelho/, 'Limitação do aparelho visível')
console.log('OK: rascunho automático protegido de sessão lenta; falhas locais explícitas')
